// APIServiceHandler is an implementation of the neoshowcase.protobuf.APIService service.
type APIServiceHandler interface {
	// GetSystemInfo システム固有情報を取得します
	GetSystemInfo(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[gen.SystemInfo], error)
	// GenerateKeyPair リポジトリ登録で使用する鍵ペアを一時的に生成します
	GenerateKeyPair(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[gen.GenerateKeyPairResponse], error)
	// GetMe 自身の情報を取得します プロキシ認証のため常に成功します
	GetMe(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[gen.User], error)
	// GetUsers 全てのユーザーの情報を取得します
	GetUsers(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[gen.GetUsersResponse], error)
	// CreateUserKey アプリコンテナSSH用の公開鍵を登録します
	CreateUserKey(context.Context, *connect.Request[gen.CreateUserKeyRequest]) (*connect.Response[gen.UserKey], error)
	// GetUserKeys 登録した公開鍵一覧を取得します
	GetUserKeys(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[gen.GetUserKeysResponse], error)
	// DeleteUserKey 登録した公開鍵を削除します
	DeleteUserKey(context.Context, *connect.Request[gen.DeleteUserKeyRequest]) (*connect.Response[emptypb.Empty], error)
	// CreateRepository リポジトリを登録します
	CreateRepository(context.Context, *connect.Request[gen.CreateRepositoryRequest]) (*connect.Response[gen.Repository], error)
	// GetRepositories リポジトリ一覧を取得します
	GetRepositories(context.Context, *connect.Request[gen.GetRepositoriesRequest]) (*connect.Response[gen.GetRepositoriesResponse], error)
	// GetRepositoryCommits コミットのメタ情報を取得します
	GetRepositoryCommits(context.Context, *connect.Request[gen.GetRepositoryCommitsRequest]) (*connect.Response[gen.GetRepositoryCommitsResponse], error)
	// GetRepository リポジトリを取得します
	GetRepository(context.Context, *connect.Request[gen.RepositoryIdRequest]) (*connect.Response[gen.Repository], error)
	// GetRepositoryRefs リポジトリの現在の有効なref一覧を取得します
	GetRepositoryRefs(context.Context, *connect.Request[gen.RepositoryIdRequest]) (*connect.Response[gen.GetRepositoryRefsResponse], error)
	// UpdateRepository リポジトリ情報を更新します
	UpdateRepository(context.Context, *connect.Request[gen.UpdateRepositoryRequest]) (*connect.Response[emptypb.Empty], error)
	// RefreshRepository 自動更新間隔を待たず、手動でリモートリポジトリの最新情報に追従させます
	RefreshRepository(context.Context, *connect.Request[gen.RepositoryIdRequest]) (*connect.Response[emptypb.Empty], error)
	// DeleteRepository リポジトリを削除します 関連する全てのアプリケーションの削除が必要です
	DeleteRepository(context.Context, *connect.Request[gen.RepositoryIdRequest]) (*connect.Response[emptypb.Empty], error)
	// CreateApplication アプリを作成します
	CreateApplication(context.Context, *connect.Request[gen.CreateApplicationRequest]) (*connect.Response[gen.Application], error)
	// GetApplications アプリ一覧を取得します
	GetApplications(context.Context, *connect.Request[gen.GetApplicationsRequest]) (*connect.Response[gen.GetApplicationsResponse], error)
	// GetApplication アプリを取得します
	GetApplication(context.Context, *connect.Request[gen.ApplicationIdRequest]) (*connect.Response[gen.Application], error)
	// UpdateApplication アプリ情報を更新します
	UpdateApplication(context.Context, *connect.Request[gen.UpdateApplicationRequest]) (*connect.Response[emptypb.Empty], error)
	// DeleteApplication アプリを削除します 先にアプリのシャットダウンが必要です
	DeleteApplication(context.Context, *connect.Request[gen.ApplicationIdRequest]) (*connect.Response[emptypb.Empty], error)
	// GetAvailableMetrics 取得可能メトリクス一覧を取得します
	GetAvailableMetrics(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[gen.AvailableMetrics], error)
	// GetApplicationMetrics アプリのメトリクスを取得します
	GetApplicationMetrics(context.Context, *connect.Request[gen.GetApplicationMetricsRequest]) (*connect.Response[gen.ApplicationMetrics], error)
	// GetOutput アプリの出力を取得します
	GetOutput(context.Context, *connect.Request[gen.GetOutputRequest]) (*connect.Response[gen.ApplicationOutputs], error)
	// GetOutputStream アプリの出力をストリーム形式で取得します
	GetOutputStream(context.Context, *connect.Request[gen.GetOutputStreamRequest], *connect.ServerStream[gen.ApplicationOutput]) error
	// GetEnvVars アプリの環境変数を取得します
	GetEnvVars(context.Context, *connect.Request[gen.ApplicationIdRequest]) (*connect.Response[gen.ApplicationEnvVars], error)
	// SetEnvVar アプリの環境変数をセットします システムによって設定された環境変数は上書きできません
	SetEnvVar(context.Context, *connect.Request[gen.SetApplicationEnvVarRequest]) (*connect.Response[emptypb.Empty], error)
	// DeleteEnvVar アプリの環境変数を削除します システムによって設定された環境変数は削除できません
	DeleteEnvVar(context.Context, *connect.Request[gen.DeleteApplicationEnvVarRequest]) (*connect.Response[emptypb.Empty], error)
	// StartApplication アプリを起動します 起動中の場合は再起動します
	StartApplication(context.Context, *connect.Request[gen.ApplicationIdRequest]) (*connect.Response[emptypb.Empty], error)
	// StopApplication アプリをシャットダウンします
	StopApplication(context.Context, *connect.Request[gen.ApplicationIdRequest]) (*connect.Response[emptypb.Empty], error)
	// GetAllBuilds すべてのアプリケーションのビルドキューを取得します
	GetAllBuilds(context.Context, *connect.Request[gen.GetAllBuildsRequest]) (*connect.Response[gen.GetBuildsResponse], error)
	// GetBuilds アプリのビルド一覧を取得します
	GetBuilds(context.Context, *connect.Request[gen.ApplicationIdRequest]) (*connect.Response[gen.GetBuildsResponse], error)
	// GetBuild アプリのビルド情報を取得します
	GetBuild(context.Context, *connect.Request[gen.BuildIdRequest]) (*connect.Response[gen.Build], error)
	// RetryCommitBuild アプリの該当コミットのビルドをやり直します
	RetryCommitBuild(context.Context, *connect.Request[gen.RetryCommitBuildRequest]) (*connect.Response[emptypb.Empty], error)
	// CancelBuild 該当ビルドが進行中の場合キャンセルします
	CancelBuild(context.Context, *connect.Request[gen.BuildIdRequest]) (*connect.Response[emptypb.Empty], error)
	// GetBuildLog 終了したビルドのログを取得します
	GetBuildLog(context.Context, *connect.Request[gen.BuildIdRequest]) (*connect.Response[gen.BuildLog], error)
	// GetBuildLogStream ビルド中のログをストリーム形式で取得します
	GetBuildLogStream(context.Context, *connect.Request[gen.BuildIdRequest], *connect.ServerStream[gen.BuildLog]) error
	// GetBuildArtifact 静的サイトアプリの場合ビルド成果物（静的ファイルのtar）を取得します
	GetBuildArtifact(context.Context, *connect.Request[gen.ArtifactIdRequest]) (*connect.Response[gen.ArtifactContent], error)
}

